// npm run build:sim — build the sim bundle and copy the fixtures next to it, so the
// Edge Functions (and scripts/determinism/deno-check.ts) use exactly what is committed.
// src/core/sim-bundle.test.ts calls buildSimFiles() and fails if the committed files differ.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { build } from 'vite';

export const SHARED = resolve('supabase/functions/_shared');
export const FIXTURES = ['mobile-1.json', 'vr-1.json'];
const BANNER =
  '// GENERATED by `npm run build:sim` from src/core/sim-entry.ts. Do not edit.\n' +
  '// Joud Bird deterministic simulation: replay(), rulesets, fixture checks. See docs/mobile.md.\n';

const lf = (s) => s.replace(/\r\n/g, '\n');

/** Build the bundle in memory. Returns its code (LF line endings). */
export async function buildSimCode() {
  const out = await build({
    configFile: resolve('vite.sim.config.ts'),
    build: { write: false },
    logLevel: 'warn',
  });
  for (const o of Array.isArray(out) ? out : [out]) {
    for (const item of o.output) {
      if (item.type === 'chunk' && item.fileName === 'joud-sim.js') return BANNER + lf(item.code);
    }
  }
  throw new Error('joud-sim.js not produced');
}

/** Every file build:sim writes: path under SHARED → contents. */
export async function buildSimFiles() {
  const code = await buildSimCode();
  if (/^\s*import\s/m.test(code)) throw new Error('the sim bundle must have no imports');
  const files = { 'joud-sim.js': code };
  for (const f of FIXTURES) {
    files[`fixtures/${f}`] = lf(readFileSync(resolve('src/core/fixtures', f), 'utf8'));
  }
  return files;
}

export async function main() {
  const files = await buildSimFiles();
  mkdirSync(resolve(SHARED, 'fixtures'), { recursive: true });
  for (const [name, text] of Object.entries(files)) writeFileSync(resolve(SHARED, name), text);
  console.log(`sim bundle: ${files['joud-sim.js'].length} bytes, ${FIXTURES.length} fixture files → ${SHARED}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await main();
